export class Multiplayer {
 constructor(onState){this.onState=onState;this.room=null;this.token=null;this.seq=0;this.pending={};this.busy=false;this.last=0;this.error='';this.laneInputs=[];this.jumpSeq=0;this.latency=0;this.lastResponseAt=0;this.restoring=false;}
 async call(action,extra={}){const started=performance.now();const abort=new AbortController();const timeout=setTimeout(()=>abort.abort(),8000);let r;try{r=await await fetch('/api/race',{signal:abort.signal,method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,code:this.room?.code,token:this.token,...extra})});}finally{clearTimeout(timeout);}const data=await r.json();if(!r.ok){const e=Error(data.error||'Connection lost');e.status=r.status;throw e;}this.latency=performance.now()-started;this.lastResponseAt=performance.now();if(data.token)this.token=data.token;this.room=data.room;const mine=this.room?.players.find(p=>p.id===this.room.you);if(mine?.seq!==undefined)this.laneInputs=this.laneInputs.filter(i=>i.seq>mine.seq);this.error='';if(mine?.seq!==undefined)this.seq=Math.max(this.seq,mine.seq);if(action!=='leave'){this.remember();this.onState(this.room);}return data;}
 remember(){try{if(this.room&&this.token)sessionStorage.setItem('kickflipRaceSession',JSON.stringify({code:this.room.code,token:this.token}));}catch{}}
 forget(){try{sessionStorage.removeItem('kickflipRaceSession');}catch{}}
 async restore(){let saved;try{saved=JSON.parse(sessionStorage.getItem('kickflipRaceSession'));}catch{}if(!saved?.code||!saved.token)return false;this.room={code:saved.code,phase:'lobby',players:[]};this.token=saved.token;this.restoring=true;try{await this.call('resume');return true;}catch(e){if(e.status===400||e.status===404){this.forget();this.room=null;this.token=null;this.onState(null);}else this.error='Reconnecting…';return false;}finally{this.restoring=false;}}
 connectionText(){if(this.error||performance.now()-this.lastResponseAt>1500)return 'Reconnecting…';return this.latency>400?'Slow connection · '+Math.round(this.latency)+' ms':'Connected · '+Math.round(this.latency)+' ms';}
 async enter(action,name,code){await this.call(action,{name,code});this.seq=0;this.laneInputs=[];this.jumpSeq=0;}
 collect(keys){for(const direction of [-1,1]){const k=direction<0?'left':'right';if(keys[k]){(this.pending.laneSteps||=[]).push(direction);this.laneInputs.push({seq:this.seq+1,direction});keys[k]=false;}}if(keys.jump)this.jumpSeq=this.seq+1;for(const k of ['jump','deliver']){if(keys[k]){this.pending[k]=true;keys[k]=false;}}if(keys.toyLeft||keys.toyRight){this.pending.toy=keys.toyLeft?-1:1;keys.toyLeft=keys.toyRight=false;}}
 tick(now,keys){if(this.restoring||!this.room||this.busy||now-this.last<160)return;this.last=now;this.busy=true;const batch=this.pending;this.pending={};const input={...batch,boost:!!(keys.boost||keys.screenBoost),brake:!!keys.brake};this.call(this.room.phase==='race'?'input':'poll',{seq:++this.seq,input}).catch(e=>{this.error=e.message;if(batch.laneSteps)this.pending.laneSteps=[...batch.laneSteps,...(this.pending.laneSteps||[])];for(const k of ['jump','deliver','toy'])if(batch[k])this.pending[k]=batch[k];}).finally(()=>this.busy=false);}
 predictedLane(target){for(const i of this.laneInputs)target=Math.max(-1,Math.min(1,target+i.direction));return target;}
 async leave(){const r=this.room;try{await this.call('leave');}catch{}this.forget();this.room=null;this.token=null;this.pending={};this.laneInputs=[];this.onState(null);}
}
